{
  "arguments": [
    {
      "stance": "pro",
      "typology": "moral",
      "ander_onderwerp": null,
      "quote_text": "Ik sprak van de week, dinsdag, voordat ik hierheen ging nog met mensen uit Groningen. Die vertelden ook weer hoe treurig het is dat de mensen in Ter Apel buiten slapen, hoe mensonterend het is en hoe inhumaan het eigenlijk is wat zich daar afspeelt. Als je met een beetje Groningse nuchterheid naar die situatie kijkt en je weet dat er een Spreidingswet is, dan zou je toch zeggen: iedereen moet zijn verantwoordelijkheid nemen om te voorkomen wat we nu zien in Ter Apel.",
      "quote_context": "Bushoff beschrijft de slechte opvangomstandigheden in Ter Apel als mensonterend en pleit voor uitvoering van de Spreidingswet om deze situatie te voorkomen.",
      "claims": []
    },
    {
      "stance": "pro",
      "typology": "factual",
      "ander_onderwerp": null,
      "quote_text": "Volgens de IND kunnen de wachttijden dan oplopen tot vijf jaar, laat de Algemene Rekenkamer weten. Dat is natuurlijk heel treurig, want ook dat leidt tot langere onzekerheid, extra belasting van de opvang, uitstel van inburgering et cetera.",
      "quote_context": "Bushoff wijst op de negatieve gevolgen van lange wachttijden voor asielprocedures, zoals onzekerheid en druk op de opvang, wat aansluit bij de pro-pool die zorgvuldigheid en adequate opvang benadrukt.",
      "claims": [
        {
          "claim_text": "wachttijden kunnen oplopen tot vijf jaar",
          "attributed_source_text": "Algemene Rekenkamer"
        },
        {
          "claim_text": "70% van de IND-capaciteit wordt ingezet voor nieuwe aanvragen",
          "attributed_source_text": "IND"
        },
        {
          "claim_text": "30% zal worden ingezet voor de bestaande 55.000 aanvragen",
          "attributed_source_text": "IND"
        }
      ]
    },
    {
      "stance": "pro",
      "typology": "moral",
      "ander_onderwerp": null,
      "quote_text": "Ik blijf het heel erg raar vinden dat er gesprekken zouden worden gevoerd met de Taliban. [...] Ik kan er met mijn hoofd eigenlijk gewoon niet bij, met een beetje gezond verstand, wil ik zeggen, dat die gesprekken gaan plaatsvinden en dat het kabinet de Europese Unie daarin zal steunen. [...] Ik kan er werkelijk waar niet met mijn hoofd bij, als ik zie wat voor verschrikkelijke dingen daar nog gebeuren.",
      "quote_context": "Bushoff bekritiseert het voeren van gesprekken met de Taliban vanwege de schending van menselijke waardigheid en de ernstige situatie in Afghanistan, wat aansluit bij de pro-pool die bescherming en ethische overwegingen centraal stelt.",
      "claims": []
    }
  ]
}

{
  "arguments": [
    {
      "stance": "contra",
      "typology": "factual",
      "ander_onderwerp": null,
      "quote_text": "De uitvoering is een enorme opgave voor de toelatingsorganisatie van ons land, terwijl de dienst al tegen metershoge stapels aanvragen aankijkt. Daarom nam de Kamer mijn motie aan om te komen met aanvullende maatregelen ter vereenvoudiging en versnelling van de asielbeoordelingsprocedure, en daarbij ook de inrichting en aansturing van de IND-werkprocessen tegen het licht te houden. We moeten voorkomen dat het nog verder vastloopt.",
      "quote_context": null,
      "claims": []
    },
    {
      "stance": "contra",
      "typology": "legal",
      "ander_onderwerp": null,
      "quote_text": "Het kan niet zo zijn dat privacywetgeving het grip krijgen op migratie dwarsboomt, zoals bijvoorbeeld bij het uitlezen van mobiele telefoons van asielzoekers, zeker nu blijkt dat dit het zoveelste punt is waarop Nederland achterblijft bij andere landen.",
      "quote_context": null,
      "claims": [
        {
          "claim_text": "Nederland blijft achter bij andere landen op het punt van het uitlezen van mobiele telefoons van asielzoekers",
          "attributed_source_text": null
        }
      ]
    },
    {
      "stance": "contra",
      "typology": "factual",
      "ander_onderwerp": null,
      "quote_text": "Ondertussen blijven gemeenten bij het COA tegen onmogelijkheden en onwil aanlopen als ze aangeven een kleine azc-locatie op te willen zetten. Het COA hanteert vaak als minimumomvang 150 opvangplekken, terwijl inmiddels alle beetjes helpen. Gaat de minister het COA duidelijk maken dat deze breedgedragen politieke wens nu echt moet worden uitgevoerd?",
      "quote_context": null,
      "claims": [
        {
          "claim_text": "Het COA hanteert vaak als minimumomvang 150 opvangplekken",
          "attributed_source_text": null
        }
      ]
    },
    {
      "stance": "contra",
      "typology": "factual",
      "ander_onderwerp": null,
      "quote_text": "De SGP is en blijft tegen de Spreidingswet, met name vanwege de dwang richting de gemeenten. Juist daarom zouden wij graag zien dat gemeenten meer regie over de asielopvang krijgen. De SGP heeft eerder voorgesteld om gemeenten de mogelijkheid te geven zelf de opvang te organiseren, waarbij zij COA-diensten inhuren. Is de minister bereid te kijken hoe er meer ruimte kan worden geboden aan gemeentelijke exploitatie, zoals gemeenten bepleiten?",
      "quote_context": null,
      "claims": []
    },
    {
      "stance": "contra",
      "typology": "factual",
      "ander_onderwerp": null,
      "quote_text": "De situatie van Syrische christenen is in de achterliggende maanden hard achteruitgegaan. Er lijkt inmiddels sprake van structurele bedreiging. De islamisering neemt toe en terreurgroepen hebben het voorzien op christenen en andere minderheden. Is de minister bereid het Syrische landenbeleid ten aanzien van religieuze minderheden te herzien?",
      "quote_context": null,
      "claims": [
        {
          "claim_text": "De situatie van Syrische christenen is in de achterliggende maanden hard achteruitgegaan",
          "attributed_source_text": null
        },
        {
          "claim_text": "Er lijkt inmiddels sprake van structurele bedreiging",
          "attributed_source_text": null
        },
        {
          "claim_text": "De islamisering neemt toe",
          "attributed_source_text": null
        },
        {
          "claim_text": "terreurgroepen hebben het voorzien op christenen en andere minderheden",
          "attributed_source_text": null
        }
      ]
    }
  ]
}

{
  "arguments": [
    {
      "stance": "contra",
      "typology": "legal",
      "ander_onderwerp": null,
      "quote_text": "Uiteindelijk is de Spreidingswet namelijk gewoon democratisch vastgesteld. Net als iedere wet moet die ook gewoon worden nageleefd. Ik vind het vreemd dat we in iedere commissie spreken over wetten die we moeten naleven, terwijl alleen bij Asiel en Migratie van een wet afgeweken mag worden die ons niet bevalt. Dat lijkt me echt niet de manier voor de toekomst.",
      "quote_context": null,
