  ]
}

{
  "arguments": [
    {
      "stance": "contra",
      "typology": "factual",
      "ander_onderwerp": null,
      "quote_text": "Maar als we de analyse maken van wat er nodig is, dan zie ik gewoon dat die instroom naar beneden moet.",
