{
  "arguments": [
    {
      "stance": "pro",
      "typology": "moral",
      "ander_onderwerp": null,
      "quote_text": "Aan de provinciale regietafels inzetten op het opvangen van nul asielzoekers past misschien binnen de letter van de Spreidingswet, maar zeker niet binnen de geest ervan. Daarmee wordt de solidariteit tussen gemeenten, waarop deze wet is gebaseerd, ondergraven.",
      "quote_context": null,
      "claims": []
    },
    {
      "stance": "pro",
      "typology": "factual",
      "ander_onderwerp": null,
      "quote_text": "Mijn fractie zal blijven herhalen dat we de impasse in de opvangcrisis alleen doorbreken als alle gemeenten hun schouders hieronder zetten.",
      "quote_context": null,
      "claims": []
    },
    {
      "stance": "pro",
      "typology": "factual",
      "ander_onderwerp": null,
      "quote_text": "Dat klinkt misschien als veel, maar als je bedenkt dat we in Nederland 342 gemeenten hebben en een gezin gemiddeld uit vier gezinsleden bestaat, dan zie je ook dat we er met enkele woningen per gemeenten al zouden zijn. Dat zou de opvangketen direct ontlasten.",
      "quote_context": null,
      "claims": [
        {
          "claim_text": "we in Nederland 342 gemeenten hebben",
          "attributed_source_text": null
        },
        {
          "claim_text": "een gezin gemiddeld uit vier gezinsleden bestaat",
          "attributed_source_text": null
        }
      ]
    },
    {
      "stance": "pro",
      "typology": "moral",
      "ander_onderwerp": null,
      "quote_text": "Tegelijkertijd moeten we oog houden voor de menselijke gevolgen van de onvermijdelijke vertragingen.",
      "quote_context": null,
      "claims": []
    },
    {
      "stance": "pro",
      "typology": "factual",
      "ander_onderwerp": null,
      "quote_text": "Mijn fractie maakt zich vooral zorgen over de veiligheid op opvanglocaties als gevolg van het onderscheid tussen de groep van voor en na 12 juni.",
      "quote_context": null,
      "claims": []
    },
    {
      "stance": "pro",
      "typology": "factual",
      "ander_onderwerp": null,
      "quote_text": "Juist daar doen zich regelmatig veiligheids- en overlastproblemen voor. Een dergelijke uitbreiding kan bovendien bijdragen aan het draagvlak voor deze opvangvormen.",
      "quote_context": null,
      "claims": []
    },
    {
      "stance": "contra",
      "typology": "factual",
      "ander_onderwerp": null,
      "quote_text": "Voor het CDA is er veel aan gelegen dat die terugkeerhubs slagen.",
      "quote_context": null,
      "claims": []
    },
    {
      "stance": "contra",
      "typology": "legal",
      "ander_onderwerp": null,
      "quote_text": "Het is natuurlijk de taak van de rechter om daaraan te toetsen, maar ziet de minister ruimte om aan de voorkant van dit traject over terugkeerhubs met de rechtspraak in gesprek te gaan over de basisvoorwaarden waaraan die hubs moeten voldoen? Natuurlijk zal iedere casus straks op zijn individuele merites beoordeeld moeten worden, maar het zou goed zijn als problemen, waar mogelijk, aan de voorkant aangepakt kunnen worden.",
      "quote_context": null,
      "claims": []
    },
    {
      "stance": "contra",
      "typology": "legal",
      "ander_onderwerp": null,
      "quote_text": "De nieuwe Terugkeerverordening biedt meer mogelijkheden om illegale vreemdelingen langer en op andere gronden vast te zetten.",
      "quote_context": null,
      "claims": []
    }
  ]
}

